do $$ begin if to_regclass('public.fin_financial_graph') is not null or to_regclass('public.fin_graph_objects') is not null or to_regprocedure('public.fin_query_graph(uuid,text,uuid,text,uuid,text,text,date,integer,integer)') is not null or (select value from public.fin_settings where key='schema_version') <> 'financial-passport-entities-1' then raise exception 'Graph rollback incomplete'; end if; end $$;
